//! Built-in skybox templates. Each one is six 512x512 JPEG faces (kept small
//! on purpose; they are BC1-encoded into Roblox's .tex format when applied,
//! exactly like a face the person picks themselves).
//!
//! Generated from the community skybox packs the project owner supplied;
//! the original authors are not recorded in those packs.

/// Face order: ft, bk, lf, rt, up, dn.
pub struct Preset {
    pub slug: &'static str,
    pub name: &'static str,
    pub faces: [&'static [u8]; 6],
}

pub const FACE_KEYS: [&str; 6] = ["ft", "bk", "lf", "rt", "up", "dn"];

